@testset "Struct tests" begin
    using Test, PortfolioOptimisers, AverageShiftedHistograms, Dates, Clarabel, CSV,
          TimeSeries
    @testset "VecScalar" begin
        @test_throws IsEmptyError VecScalar(; v = Float64[], s = 1)
        @test_throws DomainError VecScalar(; v = [Inf, Inf, NaN], s = 1)
        @test_throws DomainError VecScalar(; v = [1.0, -2.0, 3.0], s = Inf)
        vs = VecScalar(; v = [1.0, -2.0, 3.0], s = 2)
        @test vs.v == [1.0, -2.0, 3.0]
        @test vs.s == 2
    end
    @testset "Constructor validation" begin
        @test_throws IsNonFiniteError ExcessExpectedReturns(; rf = Inf)
        @test_throws IsNonFiniteError MeanReturnRiskRatio(; rf = NaN)
        @test_throws IsNonFiniteError ExpectedReturnRiskRatio(; rf = -Inf)
        @test_throws DomainError NearestQuantilePrediction(; q = 1.5)
        @test_throws DomainError NearestQuantilePrediction(; q = -0.1)
        @test_throws DomainError KatzCentrality(; alpha = 0.0)
        @test_throws DomainError KatzCentrality(; alpha = -0.3)
        @test_throws DomainError GreedyAllocation(; unit = 0)
        @test_throws DomainError GreedyAllocation(; unit = -1)
        # FiniteAllocationInput (U4)
        @test isa(FiniteAllocationInput(; w = [0.5, 0.5], prices = [10.0, 20.0]),
                  PortfolioOptimisers.AbstractEstimator)
        @test FiniteAllocationInput(; w = [0.5, 0.5], prices = [10.0, 20.0]).cash == 1e6
        @test_throws PortfolioOptimisers.IsEmptyError FiniteAllocationInput(; w = Float64[],
                                                                            prices = Float64[])
        @test_throws DimensionMismatch FiniteAllocationInput(; w = [0.5],
                                                             prices = [1.0, 2.0])
        @test_throws DomainError FiniteAllocationInput(; w = [1.0], prices = [1.0],
                                                       cash = -5.0)
        @test_throws PortfolioOptimisers.IsNothingError FiniteAllocationInput(; w = [1.0],
                                                                              prices = [1.0],
                                                                              fees = Fees())
    end
    @testset "Norms" begin
        @test isapprox(PortfolioOptimisers.norm_error(L1Norm(), [0.5, 0.5], [0.6, 0.4], 2),
                       PortfolioOptimisers.norm_error(L1Norm(), [0.5, 0.5] - [0.6, 0.4], 2))
        @test isapprox(PortfolioOptimisers.norm_error(L2Norm(), [0.5, 0.5], [0.6, 0.4], 2),
                       PortfolioOptimisers.norm_error(L2Norm(), [0.5, 0.5] - [0.6, 0.4], 2))
        @test isapprox(PortfolioOptimisers.norm_error(LpNorm(), [0.5, 0.5], [0.6, 0.4], 2),
                       PortfolioOptimisers.norm_error(LpNorm(), [0.5, 0.5] - [0.6, 0.4], 2))
        @test isapprox(PortfolioOptimisers.norm_error(LInfNorm(), [0.5, 0.5], [0.6, 0.4],
                                                      2),
                       PortfolioOptimisers.norm_error(LInfNorm(), [0.5, 0.5] - [0.6, 0.4],
                                                      2))
    end
    @testset "ReturnsResult" begin
        X = rand(3, 4)
        F = rand(3, 2)
        B1 = rand(3, 4)
        B2 = rand(3)
        iv = rand(3, 4)
        ivpa = rand(4)
        nx = string.(1:4)
        nf = string.(1:2)
        nb1 = string.(1:4)
        nb2 = ["1"]
        ts = Date(2020, 1, 1) .+ Day.(0:2)
        @test_throws IsNonFiniteError PortfolioOptimisers.assert_all_finite([1 NaN; 3 4])
        @test_throws IsNothingError ReturnsResult(; nx = nothing, X = X)
        @test_throws IsNothingError ReturnsResult(; nx = nx)
        @test_throws IsEmptyError ReturnsResult(; nx = String[], X = X)
        @test_throws IsEmptyError ReturnsResult(; nx = nx, X = Matrix{Float64}(undef, 0, 0))
        @test_throws DimensionMismatch ReturnsResult(; nx = nx, X = rand(3, 5))

        @test_throws IsNothingError ReturnsResult(; nf = nothing, F = F)
        @test_throws IsNothingError ReturnsResult(; nf = nf)
        @test_throws IsEmptyError ReturnsResult(; nf = String[], F = F)
        @test_throws IsEmptyError ReturnsResult(; nf = nf, F = Matrix{Float64}(undef, 0, 0))
        @test_throws DimensionMismatch ReturnsResult(; nf = nf, F = rand(3, 5))

        @test_throws DimensionMismatch ReturnsResult(; nx = nx, X = X, nf = nf,
                                                     F = rand(4, 2))

        @test_throws IsEmptyError ReturnsResult(; ts = Date[])
        @test_throws IsNothingError ReturnsResult(; ts = ts)
        @test_throws DimensionMismatch ReturnsResult(; ts = ts, nx = nx, X = rand(2, 4))
        @test_throws DimensionMismatch ReturnsResult(; ts = ts, nf = nf, F = rand(2, 2))

        @test_throws IsEmptyError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                                iv = Matrix{Float64}(undef, 0, 0))
        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = [Inf Inf])
        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = [0 -1])

        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = iv, ivpa = 0)
        @test_throws IsEmptyError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                                iv = iv, ivpa = Float64[])
        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = iv, ivpa = [0])
        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = iv, ivpa = Inf)
        @test_throws DomainError ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F,
                                               iv = iv, ivpa = [Inf; Inf])
        @test_throws DimensionMismatch ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf,
                                                     F = F, iv = iv, ivpa = [1])

        rr = ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F, nb = nb1, B = B1,
                           iv = iv, ivpa = ivpa)
        @test rr.ts === ts
        @test rr.nx === nx
        @test rr.X === X
        @test rr.nf === nf
        @test rr.F === F
        @test rr.nb === nb1
        @test rr.B === B1
        @test rr.iv === iv
        @test rr.ivpa === ivpa

        rr = ReturnsResult(; ts = ts, nx = nx, X = X, nf = nf, F = F, nb = nb2, B = B2,
                           iv = iv, ivpa = 1)
        @test rr.ivpa == 1
        @test rr.nb === nb2
        @test rr.B === B2

        rr = ReturnsResult()
        @test isnothing(rr.ts)
        @test isnothing(rr.nx)
        @test isnothing(rr.X)
        @test isnothing(rr.nf)
        @test isnothing(rr.F)
        @test isnothing(rr.iv)
        @test isnothing(rr.ivpa)
    end
    @testset "Denoise" begin
        @test_throws DomainError ShrunkDenoise(; alpha = -eps())
        @test_throws DomainError ShrunkDenoise(; alpha = 1.0 + eps())
        sd = ShrunkDenoise(; alpha = 0.5)
        @test sd.alpha == 0.5

        @test_throws DomainError Denoise(; m = 1)
        @test_throws DomainError Denoise(; n = 1)

        dn = Denoise()
        @test dn.alg == ShrunkDenoise()
        @test dn.args == Tuple{}()
        @test dn.kwargs == NamedTuple{}()
        @test dn.kernel === AverageShiftedHistograms.Kernels.gaussian
        @test dn.m == 10
        @test dn.n == 1000

        dn = Denoise(; alg = FixedDenoise(), args = (1,), kwargs = (foo = 2,),
                     kernel = AverageShiftedHistograms.Kernels.logistic, m = 5, n = 20)
        @test dn.alg == FixedDenoise()
        @test dn.args == (1,)
        @test dn.kwargs == (foo = 2,)
        @test dn.kernel === AverageShiftedHistograms.Kernels.logistic
        @test dn.m == 5
        @test dn.n == 20
    end
    @testset "Detone" begin
        @test_throws DomainError Detone(; n = 0)
        dt = Detone()
        @test dt.n == 1
        dt = Detone(; n = 5)
        @test dt.n == 5
    end
    @testset "Solver" begin
        @test_throws IsEmptyError Solver(; solver = nothing, settings = Dict{String, Any}())
        @test_throws IsEmptyError Solver(; solver = nothing, settings = Pair{String, Any}[])

        s = Solver(; solver = nothing)
        @test s.name == ""
        @test isnothing(s.solver)
        @test isnothing(s.settings)
        @test s.check_sol == NamedTuple{}()
        @test s.add_bridges == true

        s = Solver(; name = "MySolver", solver = :X, settings = Dict("param" => 1),
                   check_sol = (foo = 2,), add_bridges = false)
        @test s.name == "MySolver"
        @test s.solver == :X
        @test s.settings == Dict("param" => 1)
        @test s.check_sol == (foo = 2,)
        @test s.add_bridges == false
    end
    @testset "JuMPResult" begin
        trials = Dict(:try => false)
        logger = SimpleLogger()
        with_logger(logger) do
            @test_logs (:warn, PortfolioOptimisers.failed_solve_msg(trials)) JuMPResult(;
                                                                                        trials = Dict(:try =>
                                                                                                          false),
                                                                                        success = false)
        end
        res = JuMPResult(; trials = trials, success = true)
        @test res.trials === trials
        @test res.success == true
    end
    @testset "failed_solve_msg" begin
        pe = PortfolioOptimisers
        trials = Dict("clarabel2" =>
                          Dict(:optimize! => ErrorException("boom\nsecond line")),
                      "clarabel1" => Dict(:assert_is_solved_and_feasible =>
                                              ArgumentError("infeasible"),
                                          :settings => Dict("verbose" => true)))
        msg = pe.failed_solve_msg(trials)
        # Deterministic (solvers sorted by name), one bounded line per failed stage.
        @test occursin("2 solver trial(s)", msg)
        @test first(findfirst("clarabel1", msg)) < first(findfirst("clarabel2", msg))
        @test occursin("clarabel1: assert_is_solved_and_feasible → ArgumentError: infeasible",
                       msg)
        @test occursin("clarabel2: optimize! → boom", msg)
        # Log hygiene: solver settings and post-first-line payloads never reach the log.
        @test !occursin("verbose", msg)
        @test !occursin("second line", msg)
        # Over-long first lines are truncated.
        long = pe.failed_solve_msg(Dict("s" => Dict(:optimize! => ErrorException("x"^500))))
        @test occursin("…", long)
        @test length(long) < 500
    end
    @testset "OWA" begin
        @test_throws DomainError NormalisedConstantRelativeRiskAversion(; g = 0)
        @test_throws DomainError NormalisedConstantRelativeRiskAversion(; g = 1)
        ncrra = NormalisedConstantRelativeRiskAversion()
        @test ncrra.g == 0.5

        ncrra = NormalisedConstantRelativeRiskAversion(; g = 0.25)
        @test ncrra.g == 0.25

        @test_throws IsEmptyError OWAJuMP(; slv = Solver[])
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), max_phi = 0)
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), max_phi = 1)
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), sc = 0)
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), sc = Inf)
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), so = 0)
        @test_throws DomainError OWAJuMP(; slv = Solver(; solver = nothing), so = Inf)

        owj = OWAJuMP(; slv = Solver(; solver = nothing))
        @test owj.slv == Solver(; solver = nothing)
        @test owj.max_phi == 0.5
        @test owj.sc == 1.0
        @test owj.so == 1.0
        @test owj.alg == MaximumEntropy()

        owj = OWAJuMP(; slv = Solver(; solver = nothing, name = "Foo"), max_phi = 0.25,
                      sc = 2.0, so = 3.0, alg = MinimumSumSquares())
        @test owj.slv == Solver(; solver = nothing, name = "Foo")
        @test owj.max_phi == 0.25
        @test owj.sc == 2.0
        @test owj.so == 3.0
        @test owj.alg == MinimumSumSquares()
    end
    @testset "Turnover" begin
        w = rand(3)
        @test_throws IsEmptyError TurnoverEstimator(; w = Float64[], val = "a" => 1)
        @test_throws DomainError TurnoverEstimator(; w = Float64[Inf], val = "a" => 1)

        @test_throws DomainError TurnoverEstimator(; w = [1], val = "a" => -1)
        @test_throws DomainError TurnoverEstimator(; w = [1], val = "a" => Inf)

        @test_throws DomainError TurnoverEstimator(; w = [1], val = ["a" => -1])
        @test_throws DomainError TurnoverEstimator(; w = [1], val = ["a" => Inf])

        @test_throws DomainError TurnoverEstimator(; w = [1], val = Dict("a" => -1))
        @test_throws DomainError TurnoverEstimator(; w = [1], val = Dict("a" => Inf))

        @test_throws IsEmptyError TurnoverEstimator(; w = [1, Inf],
                                                    val = Dict{String, Number}())
        @test_throws IsEmptyError TurnoverEstimator(; w = [1, Inf],
                                                    val = Pair{String, Number}[])

        @test_throws DomainError TurnoverEstimator(; w = [1], val =  val = "a" => 1 ,
                                                   dval = -eps())

        tn = TurnoverEstimator(; w = w, val = Dict("A" => 0.1, "B" => 0.2))
        @test tn.w === w
        @test tn.val == Dict("A" => 0.1, "B" => 0.2)
        @test isnothing(tn.dval)

        tn = TurnoverEstimator(; w = w, val = Dict("A" => 0.1, "B" => 0.2), dval = 0.2)
        @test tn.w === w
        @test tn.val == Dict("A" => 0.1, "B" => 0.2)
        @test tn.dval == 0.2

        tn = concrete_typed_array([TurnoverEstimator(; w = w, fixed = true,
                                                     val = Dict("A" => 0.1, "B" => 0.2)),
                                   TurnoverEstimator(; w = w,
                                                     val = Dict("A" => 0.1, "B" => 0.2)),
                                   Turnover(; w = w, fixed = true), Turnover(; w = w)])
        @test PortfolioOptimisers.needs_previous_weights.(tn) == [false, true, false, true]
        @test PortfolioOptimisers.needs_previous_weights(tn) == true
        tns = PortfolioOptimisers.factory(tn, [-1, -2, -3])
        for tn in tns
            if tn.fixed
                @test tn.w == w
            else
                @test tn.w == [-1, -2, -3]
            end
        end
        tns2 = PortfolioOptimisers.port_opt_view(tns, [2, 3])
        for (tn2, tn) in zip(tns2, tns)
            @test tn2.w == view(tn.w, [2, 3])
        end

        @test_throws IsEmptyError Turnover(; w = Float64[], val = 0)

        @test_throws DomainError Turnover(; w = Float64[Inf], val = 0)
        @test_throws DomainError Turnover(; w = [1], val = Inf)
        @test_throws DomainError Turnover(; w = [1], val = [Inf])
        @test_throws DomainError Turnover(; w = [1], val = -1)
        @test_throws DomainError Turnover(; w = [1], val = [-1])

        @test_throws DimensionMismatch Turnover(; w = [1], val = [1, 2])
    end
